const canvas = document.getElementById('pendulumCanvas');
const ctx = canvas.getContext('2d');

const sliderL = document.getElementById('sliderL');
const sliderG = document.getElementById('sliderG');
const valL = document.getElementById('valL');
const valG = document.getElementById('valG');
const realtimeT = document.getElementById('realtimeT');
const btnPlayPause = document.getElementById('btnPlayPause');
const playIcon = document.getElementById('playIcon');
const playText = document.getElementById('playText');
const btnReset = document.getElementById('btnReset');

let L = parseFloat(sliderL.value); // 1.0 to 5.0 m
let g = parseFloat(sliderG.value); // 1.0 to 20.0 m/s^2

let theta = Math.PI / 6; // initial angle 30 degrees
let omega = 0.0; // angular velocity
let isRunning = true;

const pivotX = canvas.width / 2;
const pivotY = 30;

function updatePeriodDisplay() {
  const period = 2 * Math.PI * Math.sqrt(L / g);
  realtimeT.textContent = period.toFixed(2) + " s";
  valL.textContent = L.toFixed(1) + " m";
  valG.textContent = g.toFixed(1) + " m/s²";
}

sliderL.addEventListener('input', (e) => {
  L = parseFloat(e.target.value);
  updatePeriodDisplay();
});

sliderG.addEventListener('input', (e) => {
  g = parseFloat(e.target.value);
  updatePeriodDisplay();
});

btnPlayPause.addEventListener('click', () => {
  isRunning = !isRunning;
  if (isRunning) {
    playIcon.textContent = '⏸';
    playText.textContent = 'Pause';
    btnPlayPause.classList.remove('bg-emerald-600', 'hover:bg-emerald-500');
    btnPlayPause.classList.add('bg-blue-600', 'hover:bg-blue-500');
  } else {
    playIcon.textContent = '▶';
    playText.textContent = 'Play';
    btnPlayPause.classList.remove('bg-blue-600', 'hover:bg-blue-500');
    btnPlayPause.classList.add('bg-emerald-600', 'hover:bg-emerald-500');
  }
});

btnReset.addEventListener('click', () => {
  theta = Math.PI / 6;
  omega = 0;
});

let lastTime = performance.now();

function animate(currentTime) {
  const dt = Math.min((currentTime - lastTime) / 1000, 0.05);
  lastTime = currentTime;

  if (isRunning) {
    // Equation of motion for simple pendulum: alpha = -(g / L) * sin(theta)
    const damping = 0.001; // slight damping
    const alpha = -(g / L) * Math.sin(theta) - damping * omega;
    omega += alpha * dt;
    theta += omega * dt;
  }

  // Draw
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Grid/background decoration
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = 0; x < canvas.width; x += 30) {
    ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height);
  }
  for (let y = 0; y < canvas.height; y += 30) {
    ctx.moveTo(0, y); ctx.lineTo(canvas.width, y);
  }
  ctx.stroke();

  // Pivot base
  ctx.fillStyle = '#475569';
  ctx.fillRect(pivotX - 35, pivotY - 8, 70, 8);

  // Angle arc / dashed equilibrium reference
  ctx.strokeStyle = '#64748b';
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(pivotX, pivotY);
  ctx.lineTo(pivotX, pivotY + 180);
  ctx.stroke();
  ctx.setLineDash([]);

  // Calculate pixel length proportional to L (range: 1m -> 60px, 5m -> 190px)
  const pixelLength = 55 + (L - 1) * 32;
  const bobX = pivotX + pixelLength * Math.sin(theta);
  const bobY = pivotY + pixelLength * Math.cos(theta);

  // Pendulum rod/string
  ctx.beginPath();
  ctx.moveTo(pivotX, pivotY);
  ctx.lineTo(bobX, bobY);
  ctx.strokeStyle = '#38bdf8';
  ctx.lineWidth = 3;
  ctx.stroke();

  // Pivot pin
  ctx.beginPath();
  ctx.arc(pivotX, pivotY, 5, 0, Math.PI * 2);
  ctx.fillStyle = '#f8fafc';
  ctx.fill();

  // Pendulum Bob (shading & glow)
  ctx.beginPath();
  const grad = ctx.createRadialGradient(bobX - 4, bobY - 4, 2, bobX, bobY, 18);
  grad.addColorStop(0, '#fca5a5');
  grad.addColorStop(0.5, '#ef4444');
  grad.addColorStop(1, '#991b1b');
  ctx.fillStyle = grad;
  ctx.arc(bobX, bobY, 16, 0, Math.PI * 2);
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = '#fef2f2';
  ctx.stroke();

  requestAnimationFrame(animate);
}

updatePeriodDisplay();
requestAnimationFrame(animate);

