const canvas = document.getElementById('chamberCanvas');
const ctx = canvas.getContext('2d');
const gCanvas = document.getElementById('gaugeCanvas');
const gCtx = gCanvas.getContext('2d');

const sliderT = document.getElementById('sliderT');
const sliderV = document.getElementById('sliderV');
const labelT = document.getElementById('labelT');
const labelV = document.getElementById('labelV');
const valT = document.getElementById('valT');
const valV = document.getElementById('valV');
const dispP = document.getElementById('dispP');
const txtCollisionRate = document.getElementById('txtCollisionRate');

const btnHeat = document.getElementById('btnHeat');
const btnCool = document.getElementById('btnCool');
const btnReset = document.getElementById('btnReset');

// Parameter Gas Ideal: P = (n * R * T) / V
// Kita kalibrasi konstanta n*R sedemikian rupa agar T=300K, V=24.6L menghasilkan P = 1.00 atm
const nR = (1.00 * 24.6) / 300; // ~ 0.082

let T = 300;
let V = 24.6;
let P = 1.00;

// Setup Partikel Gas
const PARTICLE_COUNT = 60;
const particles = [];

function initParticles() {
  particles.length = 0;
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    particles.push({
      x: 60 + Math.random() * 200,
      y: 40 + Math.random() * 180,
      vx: (Math.random() - 0.5) * 2,
      vy: (Math.random() - 0.5) * 2,
      radius: 4,
      hue: 200
    });
  }
}
initParticles();

let collisionCounter = 0;
let collisionRateDisplay = 0;
setInterval(() => {
  collisionRateDisplay = collisionCounter;
  collisionCounter = 0;
  txtCollisionRate.innerText = `Tumbukan/detik: ${collisionRateDisplay * 2}`;
}, 500);

function updateState() {
  T = parseFloat(sliderT.value);
  V = parseFloat(sliderV.value);

  // P = nRT / V
  P = (nR * T) / V;

  // Update Teks Label
  labelT.innerText = `${T} K`;
  labelV.innerText = `${V.toFixed(1)} L`;
  valT.innerText = `${T} K`;
  valV.innerText = `${V.toFixed(1)} L`;
  dispP.innerText = P.toFixed(2);

  // Ubah warna P berdasarkan besaran tekanan
  if (P > 3.0) {
    dispP.className = "text-2xl font-black text-rose-500 font-mono animate-pulse";
  } else if (P > 1.8) {
    dispP.className = "text-2xl font-black text-amber-400 font-mono";
  } else {
    dispP.className = "text-2xl font-black text-emerald-400 font-mono";
  }

  drawManometerGauge(P);
}

sliderT.addEventListener('input', updateState);
sliderV.addEventListener('input', updateState);

btnHeat.addEventListener('click', () => {
  sliderT.value = Math.min(600, parseFloat(sliderT.value) + 50);
  updateState();
});

btnCool.addEventListener('click', () => {
  sliderT.value = Math.max(100, parseFloat(sliderT.value) - 50);
  updateState();
});

btnReset.addEventListener('click', () => {
  sliderT.value = 300;
  sliderV.value = 24.6;
  updateState();
});

// Menggambar Manometer Analog Gauge
function drawManometerGauge(pressure) {
  gCtx.clearRect(0, 0, gCanvas.width, gCanvas.height);
  const cx = 72;
  const cy = 72;
  const r = 58;

  // Background Arc
  gCtx.beginPath();
  gCtx.arc(cx, cy, r, 0.75 * Math.PI, 2.25 * Math.PI);
  gCtx.lineWidth = 10;
  gCtx.strokeStyle = '#1e293b';
  gCtx.lineCap = 'round';
  gCtx.stroke();

  // Color Arc (Gradien Tekanan dari Hijau - Kuning - Merah)
  const maxP = 5.0; // Rentang gauge 0 - 5 atm
  const clampedP = Math.min(Math.max(pressure, 0), maxP);
  const ratio = clampedP / maxP;
  const targetAngle = 0.75 * Math.PI + ratio * (1.5 * Math.PI);

  const grad = gCtx.createLinearGradient(0, 0, 144, 144);
  grad.addColorStop(0, '#10b981');
  grad.addColorStop(0.5, '#f59e0b');
  grad.addColorStop(1, '#ef4444');

  gCtx.beginPath();
  gCtx.arc(cx, cy, r, 0.75 * Math.PI, targetAngle);
  gCtx.lineWidth = 10;
  gCtx.strokeStyle = grad;
  gCtx.lineCap = 'round';
  gCtx.stroke();

  // Jarum Penunjuk
  gCtx.save();
  gCtx.translate(cx, cy);
  gCtx.rotate(targetAngle);
  gCtx.beginPath();
  gCtx.moveTo(-6, 0);
  gCtx.lineTo(r - 12, 0);
  gCtx.lineWidth = 3;
  gCtx.strokeStyle = '#ffffff';
  gCtx.stroke();

  // Poros Tengah
  gCtx.beginPath();
  gCtx.arc(0, 0, 5, 0, Math.PI * 2);
  gCtx.fillStyle = '#ef4444';
  gCtx.fill();
  gCtx.restore();

  // Tick marks
  for (let i = 0; i <= 5; i++) {
    const tickRatio = i / 5;
    const tickAng = 0.75 * Math.PI + tickRatio * (1.5 * Math.PI);
    const x1 = cx + Math.cos(tickAng) * (r - 14);
    const y1 = cy + Math.sin(tickAng) * (r - 14);
    const x2 = cx + Math.cos(tickAng) * (r - 18);
    const y2 = cy + Math.sin(tickAng) * (r - 18);
    gCtx.beginPath();
    gCtx.moveTo(x1, y1);
    gCtx.lineTo(x2, y2);
    gCtx.lineWidth = 1.5;
    gCtx.strokeStyle = '#94a3b8';
    gCtx.stroke();
  }
}

// Loop Animasi Partikel dan Piston
function animate() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Dimensi Bejana Tabung
  const chamberLeft = 50;
  const chamberTop = 35;
  const chamberHeight = 190;
  const maxChamberWidth = 360;

  // Posisi Piston dihitung dari Volume V (10L s.d 40L)
  // Mapping V [10..40] -> lebar bejana [110px .. 370px]
  const currentChamberWidth = 110 + ((V - 10) / 30) * 260;
  const pistonX = chamberLeft + currentChamberWidth;

  // Dinding Luar Silinder Tabung
  ctx.lineWidth = 4;
  ctx.strokeStyle = '#64748b';
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(chamberLeft, chamberTop, currentChamberWidth, chamberHeight);

  // Border tabung (atas, kiri, bawah)
  ctx.beginPath();
  ctx.moveTo(pistonX + 30, chamberTop);
  ctx.lineTo(chamberLeft, chamberTop);
  ctx.lineTo(chamberLeft, chamberTop + chamberHeight);
  ctx.lineTo(pistonX + 30, chamberTop + chamberHeight);
  ctx.stroke();

  // Piston Head (Kepala piston geser)
  ctx.fillStyle = '#475569';
  ctx.strokeStyle = '#94a3b8';
  ctx.lineWidth = 2;
  ctx.fillRect(pistonX - 10, chamberTop + 2, 16, chamberHeight - 4);
  ctx.strokeRect(pistonX - 10, chamberTop + 2, 16, chamberHeight - 4);

  // Batang Piston (Rod)
  ctx.fillStyle = '#334155';
  ctx.fillRect(pistonX + 6, chamberTop + chamberHeight / 2 - 10, 70, 20);
  ctx.strokeRect(pistonX + 6, chamberTop + chamberHeight / 2 - 10, 70, 20);

  // Indikator Tekanan Manometer Pipa Penghubung (Chamber ke Atas)
  ctx.fillStyle = '#0ea5e9';
  ctx.fillRect(chamberLeft + 30, chamberTop - 12, 12, 12);

  // Kecepatan partikel berbanding lurus dengan sqrt(T) (v_rms ~ sqrt(T))
  const speedScale = Math.sqrt(T / 300) * 2.2;

  // Warna partikel berubah dari Biru (dingin) -> Kuning -> Merah (panas)
  const hue = Math.max(0, 240 - ((T - 100) / 500) * 240); // 240 (blue) to 0 (red)

  // Update & Draw Partikel Gas
  for (let p of particles) {
    // Normalisasi vektor kecepatan ke speedScale
    const curSpeed = Math.sqrt(p.vx * p.vx + p.vy * p.vy) || 1;
    const dirX = p.vx / curSpeed;
    const dirY = p.vy / curSpeed;

    p.x += dirX * speedScale;
    p.y += dirY * speedScale;

    // Tumbukan dinding kiri
    if (p.x - p.radius <= chamberLeft + 4) {
      p.x = chamberLeft + 4 + p.radius;
      p.vx = Math.abs(p.vx);
      collisionCounter++;
    }
    // Tumbukan piston (dinding kanan yang bergerak)
    if (p.x + p.radius >= pistonX - 10) {
      p.x = pistonX - 10 - p.radius;
      p.vx = -Math.abs(p.vx);
      collisionCounter++;
    }
    // Tumbukan dinding atas
    if (p.y - p.radius <= chamberTop + 4) {
      p.y = chamberTop + 4 + p.radius;
      p.vy = Math.abs(p.vy);
