const slider = document.getElementById('volumeSlider');
const vNaOhText = document.getElementById('vNaOhText');
const phBadge = document.getElementById('phBadge');
const beakerLiquid = document.getElementById('beakerLiquid');
const liquidLabel = document.getElementById('liquidLabel');
const buretLiquid = document.getElementById('buretLiquid');
const natureLabel = document.getElementById('natureLabel');
const statusLabel = document.getElementById('statusLabel');
const eqPointBadge = document.getElementById('eqPointBadge');
const addDropBtn = document.getElementById('addDropBtn');
const autoTitrateBtn = document.getElementById('autoTitrateBtn');
const resetBtn = document.getElementById('resetBtn');
const drop = document.getElementById('drop');
const canvas = document.getElementById('curveCanvas');
const ctx = canvas.getContext('2d');

const V_acid = 25.0; // mL
const M_acid = 0.1;  // M
const M_base = 0.1;  // M
let autoInterval = null;

function calculatePH(vBase) {
  const molAcid = (V_acid * M_acid) / 1000;
  const molBase = (vBase * M_base) / 1000;
  const totalV = (V_acid + vBase) / 1000;

  if (Math.abs(molAcid - molBase) < 1e-7) {
    return 7.00;
  } else if (molAcid > molBase) {
    const remainAcid = molAcid - molBase;
    const hConc = remainAcid / totalV;
    let ph = -Math.log10(hConc);
    return Math.max(1.0, Math.min(6.99, ph));
  } else {
    const excessBase = molBase - molAcid;
    const ohConc = excessBase / totalV;
    const poh = -Math.log10(ohConc);
    let ph = 14.0 - poh;
    return Math.max(7.01, Math.min(13.0, ph));
  }
}

// Color interpolation based on pH scale:
// pH <= 3: Merah tua/cerah (#ef4444)
// pH 4-6: Oranye/Kuning kehijauan
// pH 7: Hijau segar netral (#10b981)
// pH 8-10: Biru laut/Sian (#0ea5e9 / #3b82f6)
// pH >= 11: Ungu/Violet (#8b5cf6 / #6d28d9)
function getPHColor(ph) {
  if (ph < 3) return 'rgb(239, 68, 68)';       // Merah
  if (ph < 5) return 'rgb(249, 115, 22)';      // Oranye
  if (ph < 6.5) return 'rgb(234, 179, 8)';     // Kuning
  if (ph <= 7.5) return 'rgb(16, 185, 129)';   // Hijau netral
  if (ph < 9.5) return 'rgb(14, 165, 233)';    // Biru muda
  if (ph < 11.5) return 'rgb(59, 130, 246)';   // Biru tua
  return 'rgb(139, 92, 246)';                  // Ungu
}

function drawCurve(currentV) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const padLeft = 32;
  const padBottom = 22;
  const padTop = 10;
  const padRight = 15;
  const graphW = canvas.width - padLeft - padRight;
  const graphH = canvas.height - padTop - padBottom;

  // Grid & axis
  ctx.strokeStyle = '#334155';
  ctx.lineWidth = 1;

  // Horizontal pH lines (pH 0, 7, 14)
  [0, 7, 14].forEach(p => {
    const y = padTop + graphH - (p / 14) * graphH;
    ctx.beginPath();
    ctx.moveTo(padLeft, y);
    ctx.lineTo(padLeft + graphW, y);
    ctx.stroke();

    ctx.fillStyle = '#94a3b8';
    ctx.font = '9px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(p, padLeft - 6, y + 3);
  });

  // Vertical line at equivalence point (V = 25 mL)
  const xEq = padLeft + (25 / 50) * graphW;
  ctx.strokeStyle = 'rgba(245, 158, 11, 0.4)';
  ctx.setLineDash([3, 3]);
  ctx.beginPath();
  ctx.moveTo(xEq, padTop);
  ctx.lineTo(xEq, padTop + graphH);
  ctx.stroke();
  ctx.setLineDash([]);

  // Axis labels
  ctx.fillStyle = '#64748b';
  ctx.font = '8px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('0', padLeft, canvas.height - 8);
  ctx.fillText('25 mL (TE)', xEq, canvas.height - 8);
  ctx.fillText('50 mL', padLeft + graphW, canvas.height - 8);

  // Theoretical titration curve
  ctx.beginPath();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = '#38bdf8';

  for (let v = 0; v <= 50; v += 0.5) {
