const canvas = document.getElementById('simCanvas');
const ctx = canvas.getContext('2d');

const angleSlider = document.getElementById('angleSlider');
const v0Slider = document.getElementById('v0Slider');
const angleVal = document.getElementById('angleVal');
const v0Val = document.getElementById('v0Val');
const fireBtn = document.getElementById('fireBtn');
const resetBtn = document.getElementById('resetBtn');

const hMaxDisplay = document.getElementById('hMaxDisplay');
const xMaxDisplay = document.getElementById('xMaxDisplay');
const tTotalDisplay = document.getElementById('tTotalDisplay');

const g = 9.8;
let trajectories = [];
let activeBalls = [];
let animId = null;

function resizeCanvas() {
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width;
  canvas.height = rect.height;
  drawScene();
}
window.addEventListener('resize', resizeCanvas);

function updateTheoreticals() {
  const theta = parseFloat(angleSlider.value) * (Math.PI / 180);
  const v0 = parseFloat(v0Slider.value);

  const hmax = (v0 * v0 * Math.sin(theta) * Math.sin(theta)) / (2 * g);
  const xmax = (v0 * v0 * Math.sin(2 * theta)) / g;
  const tTotal = (2 * v0 * Math.sin(theta)) / g;

  hMaxDisplay.textContent = hmax.toFixed(2) + ' m';
  xMaxDisplay.textContent = xmax.toFixed(2) + ' m';
  tTotalDisplay.textContent = tTotal.toFixed(2) + ' s';
}

angleSlider.addEventListener('input', () => {
  angleVal.textContent = angleSlider.value + '°';
  updateTheoreticals();
  drawScene();
});

v0Slider.addEventListener('input', () => {
  v0Val.textContent = v0Slider.value + ' m/s';
  updateTheoreticals();
  drawScene();
});

const originX = 60;
function getOriginY() {
  return canvas.height - 45;
}
const scale = 1.8; // pixels per meter

function drawGrid() {
  const originY = getOriginY();
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 1;

  for (let x = originX; x < canvas.width; x += 50 * scale) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, originY);
    ctx.stroke();

    ctx.fillStyle = '#475569';
    ctx.font = '10px monospace';
    const meterVal = ((x - originX) / scale).toFixed(0);
    ctx.fillText(meterVal + 'm', x - 10, originY + 16);
  }

  for (let y = originY; y > 0; y -= 25 * scale) {
    ctx.beginPath();
    ctx.moveTo(originX, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();

    if (y < originY) {
      ctx.fillStyle = '#475569';
      ctx.font = '10px monospace';
      const meterVal = ((originY - y) / scale).toFixed(0);
      ctx.fillText(meterVal + 'm', originX - 35, y + 4);
    }
  }

  // Tanah (ground)
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(0, originY, canvas.width, canvas.height - originY);
  ctx.strokeStyle = '#10b981';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, originY);
  ctx.lineTo(canvas.width, originY);
  ctx.stroke();
}

function drawCannon(angleDeg) {
  const originY = getOriginY();
  const rad = angleDeg * (Math.PI / 180);
  const barrelLen = 35;

  ctx.save();
  ctx.translate(originX, originY);

  // Kaki / Wheel
  ctx.beginPath();
  ctx.arc(0, 0, 14, 0, Math.PI, true);
  ctx.fillStyle = '#475569';
  ctx.fill();
  ctx.strokeStyle = '#64748b';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Barrel
  ctx.rotate(-rad);
  ctx.fillStyle = '#f59e0b';
  ctx.strokeStyle = '#d97706';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(-4, -8, barrelLen, 16, [0, 4, 4, 0]);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}

function drawScene() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawGrid();

  const originY = getOriginY();

  // Trajectories lampau
