let p1 = "Bb";
let p2 = "Bb";

window.setParent = function(parentNum, genotype) {
  if (parentNum === 1) {
    p1 = genotype;
    ['BB', 'Bb', 'bb'].forEach(g => {
      const btn = document.getElementById('p1_' + g);
      if (btn) btn.className = 'allele-btn ' + (g === genotype ? 'active ' : '') + 'flex-1 py-1 text-xs font-bold rounded-lg border border-slate-300 ' + (g === genotype ? 'bg-blue-600 text-white' : 'bg-white hover:bg-blue-100') + ' transition';
    });
    document.getElementById('labelParent1').textContent = genotype;
  } else {
    p2 = genotype;
    ['BB', 'Bb', 'bb'].forEach(g => {
      const btn = document.getElementById('p2_' + g);
      if (btn) btn.className = 'allele-btn ' + (g === genotype ? 'active ' : '') + 'flex-1 py-1 text-xs font-bold rounded-lg border border-slate-300 ' + (g === genotype ? 'bg-rose-600 text-white' : 'bg-white hover:bg-rose-100') + ' transition';
    });
    document.getElementById('labelParent2').textContent = genotype;
  }
  calculatePunnett();
};

window.randomizeParents = function() {
  const options = ['BB', 'Bb', 'bb'];
  const r1 = options[Math.floor(Math.random() * options.length)];
  const r2 = options[Math.floor(Math.random() * options.length)];
  setParent(1, r1);
  setParent(2, r2);
};

function normalizeOffspring(a, b) {
  if (a === 'B' || b === 'B') {
    if (a === 'b' || b === 'b') return 'Bb';
    return 'BB';
  }
  return 'bb';
}

function calculatePunnett() {
  const gametes1 = [p1[0], p1[1]];
  const gametes2 = [p2[0], p2[1]];

  document.getElementById('allele_p1_0').textContent = gametes1[0];
  document.getElementById('allele_p1_1').textContent = gametes1[1];
  document.getElementById('allele_p2_0').textContent = gametes2[0];
  document.getElementById('allele_p2_1').textContent = gametes2[1];

  const grid = [
    [normalizeOffspring(gametes1[0], gametes2[0]), normalizeOffspring(gametes1[0], gametes2[1])],
    [normalizeOffspring(gametes1[1], gametes2[0]), normalizeOffspring(gametes1[1], gametes2[1])]
  ];

  let counts = { BB: 0, Bb: 0, bb: 0 };

  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 2; c++) {
      const res = grid[r][c];
      counts[res]++;
      const cell = document.getElementById(`cell_${r}_${c}`);
      cell.textContent = res;
      if (res === 'BB') {
        cell.className = 'p-2.5 rounded-lg border-2 border-emerald-300 bg-emerald-100 font-bold text-sm text-emerald-900 shadow-sm';
      } else if (res === 'Bb') {
        cell.className = 'p-2.5 rounded-lg border-2 border-indigo-300 bg-indigo-100 font-bold text-sm text-indigo-900 shadow-sm';
      } else {
        cell.className = 'p-2.5 rounded-lg border-2 border-rose-300 bg-rose-100 font-bold text-sm text-rose-900 shadow-sm';
      }
    }
  }

  // Update percentages
  const pctBB = (counts.BB / 4) * 100;
  const pctBb = (counts.Bb / 4) * 100;
  const pctbb = (counts.bb / 4) * 100;

  document.getElementById('pct_BB').textContent = `${pctBB}% (${counts.BB}/4)`;
  document.getElementById('pct_Bb').textContent = `${pctBb}% (${counts.Bb}/4)`;
  document.getElementById('pct_bb').textContent = `${pctbb}% (${counts.bb}/4)`;

  document.getElementById('bar_BB').style.width = pctBB + '%';
  document.getElementById('bar_Bb').style.width = pctBb + '%';
  document.getElementById('bar_bb').style.width = pctbb + '%';

  // Genotype ratio string
  const activeGeno = [];
  if (counts.BB) activeGeno.push(`${counts.BB} BB`);
  if (counts.Bb) activeGeno.push(`${counts.Bb} Bb`);
  if (counts.bb) activeGeno.push(`${counts.bb} bb`);
  document.getElementById('genoRatioText').textContent = activeGeno.join(' : ');

  // Phenotype
  const domCount = counts.BB + counts.Bb;
  const recCount = counts.bb;
  const domPct = (domCount / 4) * 100;
  const recPct = (recCount / 4) * 100;

  document.getElementById('pheno_dominant').textContent = `${domPct}%`;
  document.getElementById('pheno_dominant_count').textContent = `${domCount} dari 4`;
  document.getElementById('pheno_recessive').textContent = `${recPct}%`;
  document.getElementById('pheno_recessive_count').textContent = `${recCount} dari 4`;

  document.getElementById('phenoRatioText').textContent = `${domCount} Bulat : ${recCount} Keriput`;
}

// Initial setup
setParent(1, 'Bb');
setParent(2, 'Bb');

